require '/opt/licensed-media-panel/vendor/autoload.php';$id=(int)($argv[1]??0);if($id<1)exit(64);$app=Application::boot('/opt/licensed-media-panel');$db=$app->get(\PDO::class);$s=$db->prepare("SELECT id,domain,email FROM certificate_requests WHERE id=? AND target_type='main' AND status IN ('queued','failed','renewal_due')");$s->execute([$id]);$request=$s->fetch();if(!$request){fwrite(STDERR,"Solicitud no disponible\n");exit(65);}$domain=$request['domain'];if(!preg_match('/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/',$domain)||!filter_var($request['email'],FILTER_VALIDATE_EMAIL))exit(66);$db->prepare("UPDATE certificate_requests SET status='processing',started_at=NOW(),last_error=NULL WHERE id=?")->execute([$id]);$pipes=[];$process=proc_open(['/usr/bin/certbot','certonly','--nginx','--non-interactive','--agree-tos','--keep-until-expiring','--email',$request['email'],'--domains',$domain],[1=>['pipe','w'],2=>['pipe','w']],$pipes,null,['PATH'=>'/usr/sbin:/usr/bin:/sbin:/bin'],['bypass_shell'=>true]);if(!is_resource($process)){fwrite(STDERR,"No se pudo ejecutar certbot\n");exit(67);}$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($process);if($exit!==0){$db->prepare("UPDATE certificate_requests SET status='failed',last_error=?,completed_at=NOW() WHERE id=?")->execute([substr($stderr,0,65535),$id]);fwrite(STDERR,$stderr);exit($exit);}$path='/etc/letsencrypt/live/'.$domain.'/fullchain.pem';$certificate=is_file($path)?openssl_x509_parse((string)file_get_contents($path)):false;$expires=$certificate&&isset($certificate['validTo_time_t'])?date('Y-m-d H:i:s',$certificate['validTo_time_t']):null;$db->prepare("UPDATE certificate_requests SET status='issued',certificate_path=?,expires_at=?,last_error=NULL,completed_at=NOW(),last_renewal_at=NOW() WHERE id=?")->execute([$path,$expires,$id]);echo trim($stdout).PHP_EOL;
